import { expect, test } from '@playwright/test';

/**
 * Library on a TV, in a real browser.
 *
 * Generated by design-tools/gen-conformance.mjs from the design handoff, and
 * checked in deliberately. These assert the frame and the measurements — the
 * part visual review reliably misses. The numbers are hand-set in the mock and
 * do not round to a spacing ladder, so a later pass that tidies them would
 * silently redraw the screen. That is what this is here to stop; it is not
 * pedantry.
 *
 * Source: /home/masshiro/work/tsundoku/wave2/layout/doc/design/handoff/TV-Library.dc.html
 * Extracted at 2026-11-02T01:03:53.046Z at 1440x2400.
 *
 * Regenerating overwrites this file. Hand edits belong in a sibling spec.
 */

const base = process.env.PLAYWRIGHT_BASE_URL ?? '';

const SEL = {
	frame: 'body',
	searchCell: '.search-hint',
	continueGrid: '.cont',
	shelfTab: '.tabs nav .tab:nth-child(1)',
	coverGrid: '.grid'
};

test('Library on a TV: frame matches the handoff', async ({ page }) => {
	await page.goto(`${base}/`);
	await expect(page.locator(SEL.frame)).toBeVisible();

	const frameStyle = await page.locator(SEL.frame).evaluate((node) => {
		const cs = getComputedStyle(node);
		return {
			display: cs.display
		};
	});
	expect(frameStyle.display).toBe('block');
});

test('Library on a TV: searchCell matches the handoff', async ({ page }) => {
	await page.goto(`${base}/`);
	await expect(page.locator(SEL.searchCell)).toBeVisible();

	const searchCellStyle = await page.locator(SEL.searchCell).evaluate((node) => {
		const cs = getComputedStyle(node);
		return {
			display: cs.display,
			alignItems: cs.alignItems,
			justifyContent: cs.justifyContent,
			rowGap: cs.rowGap,
			columnGap: cs.columnGap,
			borderLeftWidth: cs.borderLeftWidth,
			fontWeight: cs.fontWeight,
			letterSpacing: cs.letterSpacing
		};
	});
	expect(searchCellStyle.display).toBe('flex');
	expect(searchCellStyle.alignItems).toBe('center');
	expect(searchCellStyle.justifyContent).toBe('flex-start');
	expect(searchCellStyle.rowGap).toBe('10px');
	expect(searchCellStyle.columnGap).toBe('10px');
	expect(searchCellStyle.borderLeftWidth).toBe('0px');
	expect(searchCellStyle.fontWeight).toBe('400');
	expect(searchCellStyle.letterSpacing).toBe('0.32px');
});

test('Library on a TV: continueGrid matches the handoff', async ({ page }) => {
	await page.goto(`${base}/`);
	await expect(page.locator(SEL.continueGrid)).toBeVisible();

	// grid-template-columns: repeat(3, minmax(0px, 1fr)) — needs a hand-written assertion (repeat/minmax).

	const continueGridStyle = await page.locator(SEL.continueGrid).evaluate((node) => {
		const cs = getComputedStyle(node);
		return {
			display: cs.display,
			rowGap: cs.rowGap,
			columnGap: cs.columnGap,
			borderTopWidth: cs.borderTopWidth,
			borderRightWidth: cs.borderRightWidth,
			borderBottomWidth: cs.borderBottomWidth,
			borderLeftWidth: cs.borderLeftWidth
		};
	});
	expect(continueGridStyle.display).toBe('grid');
	expect(continueGridStyle.rowGap).toBe('1px');
	expect(continueGridStyle.columnGap).toBe('1px');
	expect(continueGridStyle.borderTopWidth).toBe('1px');
	expect(continueGridStyle.borderRightWidth).toBe('1px');
	expect(continueGridStyle.borderBottomWidth).toBe('1px');
	expect(continueGridStyle.borderLeftWidth).toBe('1px');
});

