test('Library on a TV: coverGrid matches the handoff', async ({ page }) => {
	await page.goto(`${base}/`);
	await expect(page.locator(SEL.coverGrid)).toBeVisible();

	// authored as: 142.828px 142.828px 142.828px 142.844px 142.828px 142.828px
	const coverGridTracks = (
		(await page
			.locator(SEL.coverGrid)
			.evaluate((node) => getComputedStyle(node).gridTemplateColumns)) as string
	).split(' ');
	expect(coverGridTracks).toHaveLength(6);
	expect(Math.round(parseFloat(coverGridTracks[0]))).toBe(143);
	expect(Math.round(parseFloat(coverGridTracks[1]))).toBe(143);
	expect(Math.round(parseFloat(coverGridTracks[2]))).toBe(143);
	expect(Math.round(parseFloat(coverGridTracks[3]))).toBe(143);
	expect(Math.round(parseFloat(coverGridTracks[4]))).toBe(143);
	expect(Math.round(parseFloat(coverGridTracks[5]))).toBe(143);

	const coverGridStyle = await page.locator(SEL.coverGrid).evaluate((node) => {
		const cs = getComputedStyle(node);
		return {
			display: cs.display,
			rowGap: cs.rowGap,
			columnGap: cs.columnGap,
			borderTopWidth: cs.borderTopWidth,
			borderRightWidth: cs.borderRightWidth,
			borderBottomWidth: cs.borderBottomWidth,
			borderLeftWidth: cs.borderLeftWidth
		};
	});
	expect(coverGridStyle.display).toBe('grid');
	expect(coverGridStyle.rowGap).toBe('1px');
	expect(coverGridStyle.columnGap).toBe('1px');
	expect(coverGridStyle.borderTopWidth).toBe('1px');
	expect(coverGridStyle.borderRightWidth).toBe('1px');
	expect(coverGridStyle.borderBottomWidth).toBe('1px');
	expect(coverGridStyle.borderLeftWidth).toBe('1px');
});
